def _serialize_matrix(matrix):
    if (spsp.isspmatrix_csc(matrix) or spsp.isspmatrix_csr(matrix) or spsp.isspmatrix_bsr(matrix)):
        if matrix.size > 0:
            return_list = [matrix.data, matrix.indices, matrix.indptr, matrix.shape]
        else:
