    else:
        line_fmt = "{1}"
    pivot = line_no + 1
    output_lines = [ (pivot,line),("",tail)]
    for i in range (surrounding_lines):
        upper_ofst = i + 1
        upper_idx = line_no + upper_ofst
        lower_ofst = - upper_ofst
        lower_idx = line_no + lower_ofst
        if lower_idx >= 0:
